import json, time, urllib.request, urllib.error, sys
from datetime import datetime, timezone
from decimal import Decimal
B="http://localhost:8080"
tok=None
log=[]
def newtok():
    global tok
    r=urllib.request.Request(B+"/token",method="POST",data=b"")
    tok=json.load(urllib.request.urlopen(r))["token"]
def get(path):
    global tok
    for attempt in range(200):
        if tok is None: newtok()
        r=urllib.request.Request(B+path,headers={"Authorization":"Bearer "+tok})
        try:
            with urllib.request.urlopen(r) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as e:
            body=e.read()[:200]
            log.append((path,e.code,dict(e.headers),body))
            if e.code==404: return None
            if e.code==401: newtok(); continue
            if e.code==429:
                ra=e.headers.get("Retry-After")
                try: w=float(ra)
                except: 
                    try: w=float(json.loads(body).get("retry_after",1))
                    except: w=1
                time.sleep(w+0.05); continue
            time.sleep(0.5); continue
        except Exception as e:
            log.append((path,repr(e))); time.sleep(0.5)
    raise SystemExit("gave up "+path)
orders=[]; path="/orders?page=1"; pages=0
while path:
    d=get(path); pages+=1
    orders+=d["items"]; path=d["next"]
    tp=d["total_pages"]
print("pages",pages,"total_pages",tp,"rows",len(orders))
json.dump(orders,open("/tmp/work/orders.json","w"))
seen={}; dups=0
for o in orders:
    if o["id"] in seen:
        dups+=1
        if seen[o["id"]]!=o: print("DIFFERING DUP",seen[o["id"]],o)
    else: seen[o["id"]]=o
print("dups",dups,"distinct",len(seen))
from collections import Counter
print(Counter(o["status"] for o in seen.values()))
lo=datetime(2025,3,1,tzinfo=timezone.utc); hi=datetime(2025,6,1,tzinfo=timezone.utc)
def p(s):
    if s.endswith("Z"): s=s[:-1]+"+00:00"
    d=datetime.fromisoformat(s)
    if d.tzinfo is None: print("NAIVE",s); d=d.replace(tzinfo=timezone.utc)
    return d.astimezone(timezone.utc)
q=[o for o in seen.values() if o["status"]=="shipped" and lo<=p(o["placed_at"])<hi]
print("qualifying",len(q))
cust={}
for o in q:
    c=o["customer_id"]
    if c not in cust: cust[c]=get("/customers/"+c)
print("missing custs",[c for c,v in cust.items() if v is None])
reg={"north":0,"south":0,"east":0,"west":0}
for o in q:
    c=cust[o["customer_id"]]
    assert isinstance(o["amount_cents"],int) and isinstance(c["discount_pct"],int)
    num=o["amount_cents"]*(100-c["discount_pct"])
    reg[c["region"]]+=(num+50)//100
tot=sum(reg.values())
res={"total_cents":tot,"order_count":len(q),"duplicates_skipped":dups,"by_region":reg}
print(res)
json.dump(res,open("/workspace/result.json","w"),indent=2)
print(Counter((l[1]) for l in log if len(l)>2))
print(log[:3])
